DROP TABLE IF EXISTS `bncc_objetos_conhecimento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bncc_objetos_conhecimento` (
  `id_objeto_bncc` int unsigned NOT NULL AUTO_INCREMENT,
  `id_disciplina` int unsigned NOT NULL,
  `nome` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nome_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fonte_documento` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bncc-2018',
  `versao_dados` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_objeto_bncc`),
  UNIQUE KEY `uq_bncc_objeto` (`id_disciplina`,`nome_hash`),
  CONSTRAINT `fk_bncc_obj_disciplina` FOREIGN KEY (`id_disciplina`) REFERENCES `disciplinas` (`id_disciplina`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1024 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
