DROP TABLE IF EXISTS `competencias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `competencias` (
  `id_competencia` int unsigned NOT NULL AUTO_INCREMENT,
  `id_etapa` int unsigned DEFAULT NULL,
  `id_area` int unsigned DEFAULT NULL,
  `id_disciplina` int unsigned DEFAULT NULL,
  `tipo` enum('geral','especifica') COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descricao` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `ordem_exibicao` tinyint unsigned DEFAULT NULL,
  `etapa_key` int unsigned GENERATED ALWAYS AS (ifnull(`id_etapa`,0)) STORED NOT NULL,
  `area_key` int unsigned GENERATED ALWAYS AS (ifnull(`id_area`,0)) STORED NOT NULL,
  `disc_key` int unsigned GENERATED ALWAYS AS (ifnull(`id_disciplina`,0)) STORED NOT NULL,
  `fonte_documento` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fonte_localizador` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `versao_dados` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_competencia`),
  UNIQUE KEY `uq_competencias` (`id_etapa`,`id_area`,`codigo`),
  UNIQUE KEY `uq_competencias_escopo` (`etapa_key`,`area_key`,`disc_key`,`codigo`),
  KEY `fk_etapa_idx` (`id_etapa`),
  KEY `fk_conhecimento_idx` (`id_area`),
  KEY `fk_disciplina_3_idx` (`id_disciplina`),
  CONSTRAINT `fk_conhecimento` FOREIGN KEY (`id_area`) REFERENCES `areas_conhecimento` (`id_area`),
  CONSTRAINT `fk_disciplina_3` FOREIGN KEY (`id_disciplina`) REFERENCES `disciplinas` (`id_disciplina`),
  CONSTRAINT `fk_etapa` FOREIGN KEY (`id_etapa`) REFERENCES `etapas` (`id_etapa`)
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `competencias`
--

LOCK TABLES `competencias` WRITE;
/*!40000 ALTER TABLE `competencias` DISABLE KEYS */;
INSERT INTO `competencias` (`id_competencia`, `id_etapa`, `id_area`, `id_disciplina`, `tipo`, `codigo`, `descricao`, `ordem_exibicao`, `fonte_documento`, `fonte_localizador`, `versao_dados`) VALUES (1,NULL,NULL,NULL,'geral','01','Conhecimento: valorizar e utilizar os conhecimentos historicamente construídos sobre o mundo físico, social, cultural e digital para compreender a realidade, continuar aprendendo e contribuir para uma sociedade justa, democrática e inclusiva.',1,NULL,NULL,NULL),(2,NULL,NULL,NULL,'geral','02','Pensamento científico, crítico e criativo: exercitar a curiosidade intelectual, investigar, refletir, analisar criticamente, formular hipóteses, resolver problemas e criar soluções com base nos conhecimentos das diferentes áreas.',2,NULL,NULL,NULL),(3,NULL,NULL,NULL,'geral','03','Repertório cultural: valorizar e participar de manifestações artísticas e culturais, reconhecendo e respeitando diferentes expressões culturais.',3,NULL,NULL,NULL),(4,NULL,NULL,NULL,'geral','04','Comunicação: utilizar diferentes linguagens, como a verbal, corporal, visual, sonora e digital, para expressar e compartilhar informações, experiências, ideias e sentimentos.',4,NULL,NULL,NULL),(5,NULL,NULL,NULL,'geral','05','Cultura digital: compreender, utilizar e criar tecnologias digitais de informação e comunicação de maneira crítica, significativa, reflexiva e ética.',5,NULL,NULL,NULL),(6,NULL,NULL,NULL,'geral','06','Trabalho e projeto de vida: valorizar a diversidade de saberes e experiências culturais, compreender as relações do mundo do trabalho e realizar escolhas alinhadas à cidadania e ao próprio projeto de vida.',6,NULL,NULL,NULL),(7,NULL,NULL,NULL,'geral','07','Argumentação: argumentar com base em fatos, dados e informações confiáveis para formular, negociar e defender ideias e decisões que respeitem os direitos humanos, a consciência socioambiental e o consumo responsável.',7,NULL,NULL,NULL),(8,NULL,NULL,NULL,'geral','08','Autoconhecimento e autocuidado: conhecer-se, apreciar-se e cuidar da saúde física e emocional, reconhecendo as próprias emoções e as dos outros.',8,NULL,NULL,NULL),(9,NULL,NULL,NULL,'geral','09','Empatia e cooperação: exercitar o diálogo, a empatia e a cooperação, respeitando os direitos humanos e valorizando a diversidade de indivíduos e grupos sociais.',9,NULL,NULL,NULL),(10,NULL,NULL,NULL,'geral','10','Responsabilidade e cidadania: agir pessoal e coletivamente com autonomia, responsabilidade, flexibilidade, resiliência e determinação, com base em princípios éticos, democráticos, inclusivos, sustentáveis e solidários.',10,NULL,NULL,NULL),(11,NULL,1,NULL,'especifica','1','Compreender as linguagens como construção humana, histórica, social e cultural, de natureza dinâmica, reconhecendo-as e valorizando-as como formas de significação da realidade e expressão de subjetividades e identidades sociais e culturais.',1,NULL,NULL,NULL),(12,NULL,1,NULL,'especifica','2','Conhecer e explorar diversas práticas de linguagem (artísticas, corporais e linguísticas) em diferentes campos da atividade humana para continuar aprendendo, ampliar suas possibilidades de participação na vida social e colaborar para a construção de uma sociedade mais justa, democrática e inclusiva.',2,NULL,NULL,NULL),(13,NULL,1,NULL,'especifica','3','Utilizar diferentes linguagens – verbal (oral ou visual-motora, como Libras, e escrita), corporal, visual, sonora e digital –, para se expressar e partilhar informações, experiências, ideias e sentimentos em diferentes contextos e produzir sentidos que levem ao diálogo, à resolução de conflitos e à cooperação.',3,NULL,NULL,NULL),(14,NULL,1,NULL,'especifica','4','Utilizar diferentes linguagens para defender pontos de vista que respeitem o outro e promovam os direitos humanos, a consciência socioambiental e o consumo responsável em âmbito local, regional e global, atuando criticamente frente a questões do mundo contemporâneo.',4,NULL,NULL,NULL),(15,NULL,1,NULL,'especifica','5','Desenvolver o senso estético para reconhecer, fruir e respeitar as diversas manifestações artísticas e culturais, das locais às mundiais, inclusive aquelas pertencentes ao patrimônio cultural da humanidade, bem como participar de práticas diversificadas, individuais e coletivas, da produção artístico-cultural, com respeito à diversidade de saberes, identidades e culturas.',5,NULL,NULL,NULL),(16,NULL,1,NULL,'especifica','6','Compreender e utilizar tecnologias digitais de informação e comunicação de forma crítica, significativa, reflexiva e ética nas diversas práticas sociais (incluindo as escolares), para se comunicar por meio das diferentes linguagens e mídias, produzir conhecimentos, resolver problemas e desenvolver projetos autorais e coletivos.',6,NULL,NULL,NULL),(18,NULL,2,NULL,'especifica','1','Reconhecer que a Matemática é uma ciência humana, fruto das necessidades e preocupações de diferentes culturas, em diferentes momentos históricos, e é uma ciência viva, que contribui para solucionar problemas científicos e tecnológicos e para alicerçar descobertas e construções, inclusive com impactos no mundo do trabalho.',1,NULL,NULL,NULL),(19,NULL,2,NULL,'especifica','2','Desenvolver o raciocínio lógico, o espírito de investigação e a capacidade de produzir argumentos convincentes, recorrendo aos conhecimentos matemáticos para compreender e atuar no mundo.',2,NULL,NULL,NULL),(20,NULL,2,NULL,'especifica','3','Compreender as relações entre conceitos e procedimentos dos diferentes campos da Matemática (Aritmética, Álgebra, Geometria, Estatística e Probabilidade) e de outras áreas do conhecimento, sentindo segurança quanto à própria capacidade de construir e aplicar conhecimentos matemáticos, desenvolvendo a autoestima e a perseverança na busca de soluções.',3,NULL,NULL,NULL),(21,NULL,2,NULL,'especifica','4','Fazer observações sistemáticas de aspectos quantitativos e qualitativos presentes nas práticas sociais e culturais, de modo a investigar, organizar, representar e comunicar informações relevantes, para interpretá-las e avaliá-las crítica e eticamente, produzindo argumentos convincentes.',4,NULL,NULL,NULL),(22,NULL,2,NULL,'especifica','5','Utilizar processos e ferramentas matemáticas, inclusive tecnologias digitais disponíveis, para modelar e resolver problemas cotidianos, sociais e de outras áreas de conhecimento, validando estratégias e resultados.',5,NULL,NULL,NULL),(23,NULL,2,NULL,'especifica','6','Enfrentar situações-problema em múltiplos contextos, incluindo-se situações imaginadas, não diretamente relacionadas com o aspecto prático-utilitário, expressar suas respostas e sintetizar conclusões, utilizando diferentes registros e linguagens (gráficos, tabelas, esquemas, além de texto escrito na língua materna e outras linguagens para descrever algoritmos, como fluxogramas, e dados).',6,NULL,NULL,NULL),(24,NULL,2,NULL,'especifica','7','Desenvolver e/ou discutir projetos que abordem, sobretudo, questões de urgência social, com base em princípios éticos, democráticos, sustentáveis e solidários, valorizando a diversidade de opiniões de indivíduos e de grupos sociais, sem preconceitos de qualquer natureza.',7,NULL,NULL,NULL),(25,NULL,2,NULL,'especifica','8','Interagir com seus pares de forma cooperativa, trabalhando coletivamente no planejamento e desenvolvimento de pesquisas para responder a questionamentos e na busca de soluções para problemas, de modo a identificar aspectos consensuais ou não na discussão de uma determinada questão, respeitando o modo de pensar dos colegas e aprendendo com eles.',8,NULL,NULL,NULL),(33,NULL,3,NULL,'especifica','1','Compreender as Ciências da Natureza como empreendimento humano, e o conhecimento científico como provisório, cultural e histórico.',1,NULL,NULL,NULL),(34,NULL,3,NULL,'especifica','2','Compreender conceitos fundamentais e estruturas explicativas das Ciências da Natureza, bem como dominar processos, práticas e procedimentos da investigação científica, de modo a sentir segurança no debate de questões científicas, tecnológicas, socioambientais e do mundo do trabalho, continuar aprendendo e colaborar para a construção de uma sociedade justa, democrática e inclusiva.',2,NULL,NULL,NULL),(35,NULL,3,NULL,'especifica','3','Analisar, compreender e explicar características, fenômenos e processos relativos ao mundo natural, social e tecnológico (incluindo o digital), como também as relações que se estabelecem entre eles, exercitando a curiosidade para fazer perguntas, buscar respostas e criar soluções (inclusive tecnológicas) com base nos conhecimentos das Ciências da Natureza.',3,NULL,NULL,NULL),(36,NULL,3,NULL,'especifica','4','Avaliar aplicações e implicações políticas, socioambientais e culturais da ciência e de suas tecnologias para propor alternativas aos desafios do mundo contemporâneo, incluindo aqueles relativos ao mundo do trabalho.',4,NULL,NULL,NULL),(37,NULL,3,NULL,'especifica','5','Construir argumentos com base em dados, evidências e informações confiáveis e negociar e defender ideias e pontos de vista que promovam a consciência socioambiental e o respeito a si próprio e ao outro, acolhendo e valorizando a diversidade de indivíduos e de grupos sociais, sem preconceitos de qualquer natureza.',5,NULL,NULL,NULL),(38,NULL,3,NULL,'especifica','6','Utilizar diferentes linguagens e tecnologias digitais de informação e comunicação para se comunicar, acessar e disseminar informações, produzir conhecimentos e resolver problemas das Ciências da Natureza de forma crítica, significativa, reflexiva e ética.',6,NULL,NULL,NULL),(39,NULL,3,NULL,'especifica','7','Conhecer, apreciar e cuidar de si, do seu corpo e bem-estar, compreendendo-se na diversidade humana, fazendo-se respeitar e respeitando o outro, recorrendo aos conhecimentos das Ciências da Natureza e às suas tecnologias.',7,NULL,NULL,NULL),(40,NULL,3,NULL,'especifica','8','Agir pessoal e coletivamente com respeito, autonomia, responsabilidade, flexibilidade, resiliência e determinação, recorrendo aos conhecimentos das Ciências da Natureza para tomar decisões frente a questões científico-tecnológicas e socioambientais e a respeito da saúde individual e coletiva, com base em princípios éticos, democráticos, sustentáveis e solidários.',8,NULL,NULL,NULL),(48,NULL,4,NULL,'especifica','1','Compreender a si e ao outro como identidades diferentes, de forma a exercitar o respeito à diferença em uma sociedade plural e promover os direitos humanos.',1,NULL,NULL,NULL),(49,NULL,4,NULL,'especifica','2','Analisar o mundo social, cultural e digital e o meio técnico-científico-informacional com base nos conhecimentos das Ciências Humanas, considerando suas variações de significado no tempo e no espaço, para intervir em situações do cotidiano e se posicionar diante de problemas do mundo contemporâneo.',2,NULL,NULL,NULL),(50,NULL,4,NULL,'especifica','3','Identificar, comparar e explicar a intervenção do ser humano na natureza e na sociedade, exercitando a curiosidade e propondo ideias e ações que contribuam para a transformação espacial, social e cultural, de modo a participar efetivamente das dinâmicas da vida social.',3,NULL,NULL,NULL),(51,NULL,4,NULL,'especifica','4','Interpretar e expressar sentimentos, crenças e dúvidas com relação a si mesmo, aos outros e às diferentes culturas, com base nos instrumentos de investigação das Ciências Humanas, promovendo o acolhimento e a valorização da diversidade de indivíduos e de grupos sociais, seus saberes, identidades, culturas e potencialidades, sem preconceitos de qualquer natureza.',4,NULL,NULL,NULL),(52,NULL,4,NULL,'especifica','5','Comparar eventos ocorridos simultaneamente no mesmo espaço e em espaços variados, e eventos ocorridos em tempos diferentes no mesmo espaço e em espaços variados.',5,NULL,NULL,NULL),(53,NULL,4,NULL,'especifica','6','Construir argumentos, com base nos conhecimentos das Ciências Humanas, para negociar e defender ideias e opiniões que respeitem e promovam os direitos humanos e a consciência socioambiental, exercitando a responsabilidade e o protagonismo voltados para o bem comum e a construção de uma sociedade justa, democrática e inclusiva.',6,NULL,NULL,NULL),(54,NULL,4,NULL,'especifica','7','Utilizar as linguagens cartográfica, gráfica e iconográfica e diferentes gêneros textuais e tecnologias digitais de informação e comunicação no desenvolvimento do raciocínio espaço-temporal relacionado a localização, distância, direção, duração, simultaneidade, sucessão, ritmo e conexão.',7,NULL,NULL,NULL),(61,NULL,1,1,'especifica','1','Compreender a língua como fenômeno cultural, histórico, social, variável, heterogêneo e sensível aos contextos de uso, reconhecendo-a como meio de construção de identidades de seus usuários e da comunidade a que pertencem.',1,NULL,NULL,NULL),(62,NULL,1,1,'especifica','2','Apropriar-se da linguagem escrita, reconhecendo-a como forma de interação nos diferentes campos de atuação da vida social e utilizando-a para ampliar suas possibilidades de participar da cultura letrada, de construir conhecimentos (inclusive escolares) e de se envolver com maior autonomia e protagonismo na vida social.',2,NULL,NULL,NULL),(63,NULL,1,1,'especifica','3','Ler, escutar e produzir textos orais, escritos e multissemióticos que circulam em diferentes campos de atuação e mídias, com compreensão, autonomia, fluência e criticidade, de modo a se expressar e partilhar informações, experiências, ideias e sentimentos, e continuar aprendendo.',3,NULL,NULL,NULL),(64,NULL,1,1,'especifica','4','Compreender o fenômeno da variação linguística, demonstrando atitude respeitosa diante de variedades linguísticas e rejeitando preconceitos linguísticos.',4,NULL,NULL,NULL),(65,NULL,1,1,'especifica','5','Empregar, nas interações sociais, a variedade e o estilo de linguagem adequados à situação comunicativa, ao(s) interlocutor(es) e ao gênero do discurso/gênero textual.',5,NULL,NULL,NULL),(66,NULL,1,1,'especifica','6','Analisar informações, argumentos e opiniões manifestados em interações sociais e nos meios de comunicação, posicionando-se ética e criticamente em relação a conteúdos discriminatórios que ferem direitos humanos e ambientais.',6,NULL,NULL,NULL),(67,NULL,1,1,'especifica','7','Reconhecer o texto como lugar de manifestação e negociação de sentidos, valores e ideologias.',7,NULL,NULL,NULL),(68,NULL,1,1,'especifica','8','Selecionar textos e livros para leitura integral, de acordo com objetivos, interesses e projetos pessoais (estudo, formação pessoal, entretenimento, pesquisa, trabalho etc.).',8,NULL,NULL,NULL),(69,NULL,1,1,'especifica','9','Envolver-se em práticas de leitura literária que possibilitem o desenvolvimento do senso estético para fruição, valorizando a literatura e outras manifestações artístico-culturais como formas de acesso às dimensões lúdicas, de imaginário e encantamento, reconhecendo o potencial transformador e humanizador da experiência com a literatura.',9,NULL,NULL,NULL),(70,NULL,1,1,'especifica','10','Mobilizar práticas da cultura digital, diferentes linguagens, mídias e ferramentas digitais para expandir as formas de produzir sentidos (nos processos de compreensão e produção), aprender e refletir sobre o mundo e realizar diferentes projetos autorais.',10,NULL,NULL,NULL),(76,NULL,1,4,'especifica','1','Explorar, conhecer, fruir e analisar criticamente práticas e produções artísticas e culturais do seu entorno social, dos povos indígenas, das comunidades tradicionais brasileiras e de diversas sociedades, em distintos tempos e espaços, para reconhecer a arte como um fenômeno cultural, histórico, social e sensível a diferentes contextos e dialogar com as diversidades.',1,NULL,NULL,NULL),(77,NULL,1,4,'especifica','2','Compreender as relações entre as linguagens da Arte e suas práticas integradas, inclusive aquelas possibilitadas pelo uso das novas tecnologias de informação e comunicação, pelo cinema e pelo audiovisual, nas condições particulares de produção, na prática de cada linguagem e nas suas articulações.',2,NULL,NULL,NULL),(78,NULL,1,4,'especifica','3','Pesquisar e conhecer distintas matrizes estéticas e culturais – especialmente aquelas manifestas na arte e nas culturas que constituem a identidade brasileira –, sua tradição e manifestações contemporâneas, reelaborando-as nas criações em Arte.',3,NULL,NULL,NULL),(79,NULL,1,4,'especifica','4','Experienciar a ludicidade, a percepção, a expressividade e a imaginação, ressignificando espaços da escola e de fora dela no âmbito da Arte.',4,NULL,NULL,NULL),(80,NULL,1,4,'especifica','5','Mobilizar recursos tecnológicos como formas de registro, pesquisa e criação artística.',5,NULL,NULL,NULL),(81,NULL,1,4,'especifica','6','Estabelecer relações entre arte, mídia, mercado e consumo, compreendendo, de forma crítica e problematizadora, modos de produção e de circulação da arte na sociedade.',6,NULL,NULL,NULL),(82,NULL,1,4,'especifica','7','Problematizar questões políticas, sociais, econômicas, científicas, tecnológicas e culturais, por meio de exercícios, produções, intervenções e apresentações artísticas.',7,NULL,NULL,NULL),(83,NULL,1,4,'especifica','8','Desenvolver a autonomia, a crítica, a autoria e o trabalho coletivo e colaborativo nas artes.',8,NULL,NULL,NULL),(84,NULL,1,4,'especifica','9','Analisar e valorizar o patrimônio artístico nacional e internacional, material e imaterial, com suas histórias e diferentes visões de mundo.',9,NULL,NULL,NULL),(91,NULL,1,5,'especifica','1','Compreender a origem da cultura corporal de movimento e seus vínculos com a organização da vida coletiva e individual.',1,NULL,NULL,NULL),(92,NULL,1,5,'especifica','2','Planejar e empregar estratégias para resolver desafios e aumentar as possibilidades de aprendizagem das práticas corporais, além de se envolver no processo de ampliação do acervo cultural nesse campo.',2,NULL,NULL,NULL),(93,NULL,1,5,'especifica','3','Refletir, criticamente, sobre as relações entre a realização das práticas corporais e os processos de saúde/doença, inclusive no contexto das atividades laborais.',3,NULL,NULL,NULL),(94,NULL,1,5,'especifica','4','Identificar a multiplicidade de padrões de desempenho, saúde, beleza e estética corporal, analisando, criticamente, os modelos disseminados na mídia e discutir posturas consumistas e preconceituosas.',4,NULL,NULL,NULL),(95,NULL,1,5,'especifica','5','Identificar as formas de produção dos preconceitos, compreender seus efeitos e combater posicionamentos discriminatórios em relação às práticas corporais e aos seus participantes.',5,NULL,NULL,NULL),(96,NULL,1,5,'especifica','6','Interpretar e recriar os valores, os sentidos e os significados atribuídos às diferentes práticas corporais, bem como aos sujeitos que delas participam.',6,NULL,NULL,NULL),(97,NULL,1,5,'especifica','7','Reconhecer as práticas corporais como elementos constitutivos da identidade cultural dos povos e grupos.',7,NULL,NULL,NULL),(98,NULL,1,5,'especifica','8','Usufruir das práticas corporais, de forma autônoma, para potencializar o envolvimento em contextos de lazer, ampliar as redes de sociabilidade e a promoção da saúde.',8,NULL,NULL,NULL),(99,NULL,1,5,'especifica','9','Reconhecer o acesso às práticas corporais como direito do cidadão, propondo e produzindo alternativas para sua realização no contexto comunitário.',9,NULL,NULL,NULL),(100,NULL,1,5,'especifica','10','Experimentar, desfrutar, apreciar e criar diferentes brincadeiras, jogos, danças, ginásticas, esportes, lutas e práticas corporais de aventura, valorizando o trabalho coletivo e o protagonismo.',10,NULL,NULL,NULL),(106,NULL,1,3,'especifica','1','Identificar o lugar de si e o do outro em um mundo plurilíngue e multicultural, refletindo, criticamente, sobre como a aprendizagem da língua inglesa contribui para a inserção dos sujeitos no mundo globalizado, inclusive no que concerne ao mundo do trabalho.',1,NULL,NULL,NULL),(107,NULL,1,3,'especifica','2','Comunicar-se na língua inglesa, por meio do uso variado de linguagens em mídias impressas ou digitais, reconhecendo-a como ferramenta de acesso ao conhecimento, de ampliação das perspectivas e de possibilidades para a compreensão dos valores e interesses de outras culturas e para o exercício do protagonismo social.',2,NULL,NULL,NULL),(108,NULL,1,3,'especifica','3','Identificar similaridades e diferenças entre a língua inglesa e a língua materna/outras línguas, articulando-as a aspectos sociais, culturais e identitários, em uma relação intrínseca entre língua, cultura e identidade.',3,NULL,NULL,NULL),(109,NULL,1,3,'especifica','4','Elaborar repertórios linguístico-discursivos da língua inglesa, usados em diferentes países e por grupos sociais distintos dentro de um mesmo país, de modo a reconhecer a diversidade linguística como direito e valorizar os usos heterogêneos, híbridos e multimodais emergentes nas sociedades contemporâneas.',4,NULL,NULL,NULL),(110,NULL,1,3,'especifica','5','Utilizar novas tecnologias, com novas linguagens e modos de interação, para pesquisar, selecionar, compartilhar, posicionar-se e produzir sentidos em práticas de letramento na língua inglesa, de forma ética, crítica e responsável.',5,NULL,NULL,NULL),(111,NULL,1,3,'especifica','6','Conhecer diferentes patrimônios culturais, materiais e imateriais, difundidos na língua inglesa, com vistas ao exercício da fruição e da ampliação de perspectivas no contato com diferentes manifestações artístico-culturais.',6,NULL,NULL,NULL),(113,NULL,4,12,'especifica','1','Utilizar os conhecimentos geográficos para entender a interação sociedade-natureza e exercitar o interesse e o espírito de investigação e de resolução de problemas.',1,NULL,NULL,NULL),(114,NULL,4,12,'especifica','2','Estabelecer conexões entre diferentes temas do conhecimento geográfico, reconhecendo a importância dos objetos técnicos para a compreensão das formas como os seres humanos fazem uso dos recursos da natureza ao longo da história.',2,NULL,NULL,NULL),(115,NULL,4,12,'especifica','3','Desenvolver autonomia e senso crítico para compreensão e aplicação do raciocínio geográfico na análise da ocupação humana e produção do espaço, envolvendo os princípios de analogia, conexão, diferenciação, distribuição, extensão, localização e ordem.',3,NULL,NULL,NULL),(116,NULL,4,12,'especifica','4','Desenvolver o pensamento espacial, fazendo uso das linguagens cartográficas e iconográficas, de diferentes gêneros textuais e das geotecnologias para a resolução de problemas que envolvam informações geográficas.',4,NULL,NULL,NULL),(117,NULL,4,12,'especifica','5','Desenvolver e utilizar processos, práticas e procedimentos de investigação para compreender o mundo natural, social, econômico, político e o meio técnico-científico e informacional, avaliar ações e propor perguntas e soluções, inclusive tecnológicas, para questões que requerem conhecimentos científicos de Geografia.',5,NULL,NULL,NULL),(118,NULL,4,12,'especifica','6','Construir argumentos com base em informações geográficas, debater e defender ideias e pontos de vista que respeitem e promovam a consciência socioambiental e o respeito à biodiversidade e ao outro, sem preconceitos de qualquer natureza.',6,NULL,NULL,NULL),(119,NULL,4,12,'especifica','7','Agir pessoal e coletivamente com respeito, autonomia, responsabilidade, flexibilidade, resiliência e determinação, propondo ações sobre as questões socioambientais, com base em princípios éticos, democráticos, sustentáveis e solidários.',7,NULL,NULL,NULL),(120,NULL,4,11,'especifica','1','Compreender acontecimentos históricos, relações de poder e processos e mecanismos de transformação e manutenção das estruturas sociais, políticas, econômicas e culturais ao longo do tempo e em diferentes espaços para analisar, posicionar-se e intervir no mundo contemporâneo.',1,NULL,NULL,NULL),(121,NULL,4,11,'especifica','2','Compreender a historicidade no tempo e no espaço, relacionando acontecimentos e processos de transformação e manutenção das estruturas sociais, políticas, econômicas e culturais, bem como problematizar os significados das lógicas de organização cronológica.',2,NULL,NULL,NULL),(122,NULL,4,11,'especifica','3','Elaborar questionamentos, hipóteses, argumentos e proposições em relação a documentos, interpretações e contextos históricos específicos, recorrendo a diferentes linguagens e mídias, exercitando a empatia, o diálogo, a resolução de conflitos, a cooperação e o respeito.',3,NULL,NULL,NULL),(123,NULL,4,11,'especifica','4','Identificar interpretações que expressem visões de diferentes sujeitos, culturas e povos com relação a um mesmo contexto histórico, e posicionar-se criticamente com base em princípios éticos, democráticos, inclusivos, sustentáveis e solidários.',4,NULL,NULL,NULL),(124,NULL,4,11,'especifica','5','Analisar e compreender o movimento de populações e mercadorias no tempo e no espaço e seus significados históricos, levando em conta o respeito e a solidariedade com as diferentes populações.',5,NULL,NULL,NULL),(125,NULL,4,11,'especifica','6','Compreender e problematizar os conceitos e procedimentos norteadores da produção historiográfica.',6,NULL,NULL,NULL),(126,NULL,4,11,'especifica','7','Produzir, avaliar e utilizar tecnologias digitais de informação e comunicação de modo crítico, ético e responsável, compreendendo seus significados para os diferentes grupos ou estratos sociais.',7,NULL,NULL,NULL),(129,3,3,NULL,'especifica','1','Analisar fenômenos naturais e processos tecnológicos, com base nas relações entre matéria e energia, para propor ações individuais e coletivas que aperfeiçoem processos produtivos, minimizem impactos socioambientais e melhorem as condições de vida em âmbito local, regional e/ou global.',1,NULL,NULL,NULL),(130,3,3,NULL,'especifica','2','Construir e utilizar interpretações sobre a dinâmica da Vida, da Terra e do Cosmos para elaborar argumentos, realizar previsões sobre o funcionamento e a evolução dos seres vivos e do Universo, e fundamentar decisões éticas e responsáveis.',2,NULL,NULL,NULL),(131,3,3,NULL,'especifica','3','Analisar situações-problema e avaliar aplicações do conhecimento científico e tecnológico e suas implicações no mundo, utilizando procedimentos e linguagens próprios das Ciências da Natureza, para propor soluções que considerem demandas locais, regionais e/ou globais, e comunicar suas descobertas e conclusões a públicos variados, em diversos contextos e por meio de diferentes mídias e tecnologias digitais de informação e comunicação (TDIC).',3,NULL,NULL,NULL),(132,3,4,NULL,'especifica','1','Analisar processos políticos, econômicos, sociais, ambientais e culturais nos âmbitos local, regional, nacional e mundial em diferentes tempos, a partir de procedimentos epistemológicos e científicos, de modo a compreender e posicionar-se criticamente com relação a esses processos e às possíveis relações entre eles.',1,NULL,NULL,NULL),(133,3,4,NULL,'especifica','2','Analisar a formação de territórios e fronteiras em diferentes tempos e espaços, mediante a compreensão dos processos sociais, políticos, econômicos e culturais geradores de conflito e negociação, desigualdade e igualdade, exclusão e inclusão e de situações que envolvam o exercício arbitrário do poder.',2,NULL,NULL,NULL),(134,3,4,NULL,'especifica','3','Contextualizar, analisar e avaliar criticamente as relações das sociedades com a natureza e seus impactos econômicos e socioambientais, com vistas à proposição de soluções que respeitem e promovam a consciência e a ética socioambiental e o consumo responsável em âmbito local, regional, nacional e global.',3,NULL,NULL,NULL),(135,3,4,NULL,'especifica','4','Analisar as relações de produção, capital e trabalho em diferentes territórios, contextos e culturas, discutindo o papel dessas relações na construção, consolidação e transformação das sociedades.',4,NULL,NULL,NULL),(136,3,4,NULL,'especifica','5','Reconhecer e combater as diversas formas de desigualdade e violência, adotando princípios éticos, democráticos, inclusivos e solidários, e respeitando os Direitos Humanos.',5,NULL,NULL,NULL),(137,3,4,NULL,'especifica','6','Participar, pessoal e coletivamente, do debate público de forma consciente e qualificada, respeitando diferentes posições, com vistas a possibilitar escolhas alinhadas ao exercício da cidadania e ao seu projeto de vida, com liberdade, autonomia, consciência crítica e responsabilidade.',6,NULL,NULL,NULL),(138,3,1,NULL,'especifica','1','Compreender o funcionamento das diferentes linguagens e práticas (artísticas, corporais e verbais) e mobilizar esses conhecimentos na recepção e produção de discursos nos diferentes campos de atuação social e nas diversas mídias, para ampliar as formas de participação social, o entendimento e as possibilidades de explicação e interpretação crítica da realidade e para continuar aprendendo.',1,NULL,NULL,NULL),(139,3,1,NULL,'especifica','2','Compreender os processos identitários, conflitos e relações de poder que permeiam as práticas sociais de linguagem, respeitar as diversidades, a pluralidade de ideias e posições e atuar socialmente com base em princípios e valores assentados na democracia, na igualdade e nos Direitos Humanos, exercitando a empatia, o diálogo, a resolução de conflitos e a cooperação, e combatendo preconceitos de qualquer natureza.',2,NULL,NULL,NULL),(140,3,1,NULL,'especifica','3','Utilizar diferentes linguagens (artísticas, corporais e verbais) para exercer, com autonomia e colaboração, protagonismo e autoria na vida pessoal e coletiva, de forma crítica, criativa, ética e solidária, defendendo pontos de vista que respeitem o outro e promovam os Direitos Humanos, a consciência socioambiental e o consumo responsável, em âmbito local, regional e global.',3,NULL,NULL,NULL),(141,3,1,NULL,'especifica','4','Compreender as línguas como fenômeno (geo)político, histórico, social, variável, heterogêneo e sensível aos contextos de uso, reconhecendo-as e vivenciando-as como formas de expressões identitárias, pessoais e coletivas, bem como respeitando as variedades linguísticas e agindo no enfrentamento de preconceitos de qualquer natureza.',4,NULL,NULL,NULL),(142,3,1,NULL,'especifica','5','Compreender os múltiplos aspectos que envolvem a produção de sentidos nas práticas sociais da cultura corporal de movimento, reconhecendo-as e vivenciando-as como formas de expressão de valores e identidades, em uma perspectiva democrática e de respeito à diversidade.',5,NULL,NULL,NULL),(143,3,1,NULL,'especifica','6','Apreciar esteticamente as mais diversas produções artísticas e culturais, considerando suas características locais, regionais e globais, e mobilizar seus conhecimentos sobre as linguagens artísticas para dar significado e (re)construir produções autorais individuais e coletivas, de maneira crítica e criativa, com respeito à diversidade de saberes, identidades e culturas.',6,NULL,NULL,NULL),(144,3,1,NULL,'especifica','7','Mobilizar práticas de linguagem no universo digital, considerando as dimensões técnicas, críticas, criativas, éticas e estéticas, para expandir as formas de produzir sentidos, de engajar-se em práticas autorais e coletivas, e de aprender a aprender nos campos da ciência, cultura, trabalho, informação e vida pessoal e coletiva.',7,NULL,NULL,NULL),(145,3,2,NULL,'especifica','1','Utilizar estratégias, conceitos e procedimentos matemáticos para interpretar situações em diversos contextos, sejam atividades cotidianas, sejam fatos das Ciências da Natureza e Humanas, ou ainda questões econômicas ou tecnológicas, divulgados por diferentes meios, de modo a consolidar uma formação científica geral.',1,NULL,NULL,NULL),(146,3,2,NULL,'especifica','2','Articular conhecimentos matemáticos ao propor e/ou participar de ações para investigar desafios do mundo contemporâneo e tomar decisões éticas e socialmente responsáveis, com base na análise de problemas de urgência social, como os voltados a situações de saúde, sustentabilidade, das implicações da tecnologia no mundo do trabalho, entre outros, recorrendo a conceitos, procedimentos e linguagens próprios da Matemática.',2,NULL,NULL,NULL),(147,3,2,NULL,'especifica','3','Utilizar estratégias, conceitos e procedimentos matemáticos, em seus campos – Aritmética, Álgebra, Grandezas e Medidas, Geometria, Probabilidade e Estatística –, para interpretar, construir modelos e resolver problemas em diversos contextos, analisando a plausibilidade dos resultados e a adequação das soluções propostas, de modo a construir argumentação consistente.',3,NULL,NULL,NULL),(148,3,2,NULL,'especifica','4','Compreender e utilizar, com flexibilidade e fluidez, diferentes registros de representação matemáticos (algébrico, geométrico, estatístico, computacional etc.), na busca de solução e comunicação de resultados de problemas, de modo a favorecer a construção e o desenvolvimento do raciocínio matemático.',4,NULL,NULL,NULL),(149,3,2,NULL,'especifica','5','Investigar e estabelecer conjecturas a respeito de diferentes conceitos e propriedades matemáticas, empregando recursos e estratégias como observação de padrões, experimentações e tecnologias digitais, identificando a necessidade, ou não, de uma demonstração cada vez mais formal na validação das referidas conjecturas.',5,NULL,NULL,NULL);
