DROP TABLE IF EXISTS `conhecimento_ano_sugestoes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `conhecimento_ano_sugestoes` (
  `id_sugestao` int unsigned NOT NULL AUTO_INCREMENT,
  `id_conhecimento` int unsigned NOT NULL,
  `id_ano_escolar` int unsigned NOT NULL,
  `id_habilidade` int unsigned NOT NULL,
  `id_sugestao_bncc` int unsigned DEFAULT NULL,
  `origem_sugestao` enum('VINCULO_EXISTENTE','SUGESTAO_BNCC') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_sugestao` enum('PENDENTE','APROVADA','REJEITADA') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDENTE',
  PRIMARY KEY (`id_sugestao`),
  UNIQUE KEY `uq_conhecimento_ano_habilidade` (`id_conhecimento`,`id_ano_escolar`,`id_habilidade`),
  KEY `fk_cas_ano_escolar` (`id_ano_escolar`),
  KEY `fk_cas_habilidade` (`id_habilidade`),
  KEY `fk_cas_sugestao_bncc` (`id_sugestao_bncc`),
  CONSTRAINT `fk_cas_ano_escolar` FOREIGN KEY (`id_ano_escolar`) REFERENCES `anos_escolares` (`id_ano_escolar`),
  CONSTRAINT `fk_cas_conhecimento` FOREIGN KEY (`id_conhecimento`) REFERENCES `conhecimentos` (`id_conhecimento`),
  CONSTRAINT `fk_cas_habilidade` FOREIGN KEY (`id_habilidade`) REFERENCES `habilidades_bncc` (`id_habilidade`),
  CONSTRAINT `fk_cas_sugestao_bncc` FOREIGN KEY (`id_sugestao_bncc`) REFERENCES `conhecimento_habilidade_sugestoes` (`id_sugestao`)
) ENGINE=InnoDB AUTO_INCREMENT=639 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

