DROP TABLE IF EXISTS `conhecimento_bncc_objeto_sugestoes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `conhecimento_bncc_objeto_sugestoes` (
  `id_sugestao` int unsigned NOT NULL AUTO_INCREMENT,
  `id_conhecimento` int unsigned NOT NULL,
  `id_objeto_bncc` int unsigned NOT NULL,
  `total_palavras` smallint unsigned NOT NULL,
  `palavras_encontradas` smallint unsigned NOT NULL,
  `pontuacao` decimal(5,2) NOT NULL,
  `criterio` enum('FRASE_CONTIDA','TODAS_AS_PALAVRAS','CORRESPONDENCIA_PARCIAL') COLLATE utf8mb4_unicode_ci NOT NULL,
  `posicao` tinyint unsigned NOT NULL,
  `status_sugestao` enum('PENDENTE','APROVADA','REJEITADA') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDENTE',
  `criado_em` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_sugestao`),
  UNIQUE KEY `uq_conhecimento_objeto_sugestao` (`id_conhecimento`,`id_objeto_bncc`),
  KEY `idx_cbos_status_conhecimento` (`status_sugestao`,`id_conhecimento`),
  KEY `fk_cbos_objeto` (`id_objeto_bncc`),
  CONSTRAINT `fk_cbos_conhecimento` FOREIGN KEY (`id_conhecimento`) REFERENCES `conhecimentos` (`id_conhecimento`),
  CONSTRAINT `fk_cbos_objeto` FOREIGN KEY (`id_objeto_bncc`) REFERENCES `bncc_objetos_conhecimento` (`id_objeto_bncc`)
) ENGINE=InnoDB AUTO_INCREMENT=256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
