--
-- Table structure for table `conhecimentos`
--

DROP TABLE IF EXISTS `conhecimentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `conhecimentos` (
  `id_conhecimento` int unsigned NOT NULL AUTO_INCREMENT,
  `id_disciplina` int unsigned DEFAULT NULL,
  `id_area` int unsigned DEFAULT NULL,
  `id_objeto` int unsigned DEFAULT NULL,
  `titulo` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descricao` text COLLATE utf8mb4_unicode_ci,
  `classificacao` enum('bncc','desdobramento','complementar') COLLATE utf8mb4_unicode_ci NOT NULL,
  `ordem_exibicao` smallint NOT NULL,
  `ativo` tinyint NOT NULL DEFAULT '1',
  PRIMARY KEY (`id_conhecimento`),
  KEY `fk_disciplina_2_idx` (`id_disciplina`),
  KEY `fk_objeto_idx` (`id_objeto`),
  KEY `fk_conhecimentos_area` (`id_area`),
  KEY `idx_conh_disc_ativo_ordem` (`id_disciplina`,`ativo`,`ordem_exibicao`),
  KEY `idx_conh_classificacao` (`classificacao`,`ativo`),
  CONSTRAINT `fk_conhecimentos_area` FOREIGN KEY (`id_area`) REFERENCES `areas_conhecimento` (`id_area`),
  CONSTRAINT `fk_disciplina_2` FOREIGN KEY (`id_disciplina`) REFERENCES `disciplinas` (`id_disciplina`),
  CONSTRAINT `fk_objeto` FOREIGN KEY (`id_objeto`) REFERENCES `objetos_conhecimento` (`id_objeto`),
  CONSTRAINT `chk_conhecimentos_area_disciplina` CHECK (((`id_area` is not null) or (`id_disciplina` is not null)))
) ENGINE=InnoDB AUTO_INCREMENT=319 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

