INSERT INTO `objetos_conhecimento` VALUES (1,1,'Sistemas de numeração','Sistemas de representação numérica, origem dos números e diferentes formas de registrar quantidades.',1),(2,1,'Números naturais','Representação, leitura, escrita, comparação, ordenação e propriedades dos números naturais.',2),(3,1,'Operações com números naturais','Adição, subtração, multiplicação e divisão, seus significados, propriedades e estratégias de cálculo.',3),(4,1,'Divisibilidade','Múltiplos, divisores, critérios de divisibilidade, números primos e decomposição em fatores primos.',4),(5,1,'Frações','Representação, comparação, equivalência, simplificação e operações com números fracionários.',5),(6,1,'Números decimais','Representação decimal, valor posicional, comparação, ordenação e operações com números decimais.',6),(7,1,'Números inteiros','Números positivos e negativos, representação na reta numérica e operações com inteiros.',7),(8,1,'Números racionais','Representações fracionária e decimal, comparação, ordenação e operações com números racionais.',8),(9,1,'Números reais','Conjunto dos números reais, representação na reta numérica e relações entre seus subconjuntos.',9),(10,1,'Potenciação e radiciação','Potências, raízes, propriedades operatórias e relações entre potenciação e radiciação.',10),(11,1,'Razão, proporção e porcentagem','Relações proporcionais, escalas, taxas, porcentagens e aplicações em situações cotidianas.',11),(12,2,'Sequências e padrões','Identificação, descrição, representação e construção de sequências numéricas e figurais.',1),(13,2,'Regularidades e propriedades da igualdade','Reconhecimento de regularidades, equivalências e propriedades da igualdade.',2),(14,2,'Expressões algébricas','Linguagem algébrica, variáveis, incógnitas, termos e valor numérico de expressões.',3),(15,2,'Equações e inequações','Representação e resolução de equações e inequações em diferentes contextos.',4),(16,2,'Sistemas de equações','Representação e resolução de sistemas de equações e interpretação de suas soluções.',5),(17,2,'Proporcionalidade e relações entre grandezas','Grandezas diretamente e inversamente proporcionais e relações entre variáveis.',6),(18,2,'Funções','Conceito de função, domínio, imagem, representação algébrica, tabelas e gráficos.',7),(19,3,'Localização e deslocamento','Localização de pontos, trajetos, orientação espacial e representação no plano.',1),(20,3,'Figuras geométricas planas','Reconhecimento, classificação e propriedades das figuras geométricas bidimensionais.',2),(21,3,'Ângulos e suas medidas','Identificação, classificação, construção e medição de ângulos.',3),(22,3,'Polígonos','Elementos, classificação, propriedades e relações entre polígonos.',4),(23,3,'Circunferência e círculo','Elementos da circunferência e do círculo, comprimento e área.',5),(24,3,'Simetria, congruência e semelhança','Transformações geométricas, simetrias, figuras congruentes e figuras semelhantes.',6),(25,3,'Figuras geométricas espaciais','Reconhecimento, classificação e representação de sólidos geométricos.',7),(26,3,'Relações métricas e geometria espacial','Relações métricas em figuras planas e espaciais, incluindo aplicações do Teorema de Pitágoras.',8),(27,4,'Unidades de medida e conversões','Sistemas de unidades, instrumentos de medição e conversões entre unidades.',1),(28,4,'Comprimento, perímetro e área','Medição de comprimentos, cálculo de perímetros e determinação de áreas.',2),(29,4,'Massa e capacidade','Unidades, instrumentos, estimativas e operações envolvendo massa e capacidade.',3),(30,4,'Tempo e temperatura','Medidas de tempo e temperatura, conversões e interpretação de informações.',4),(31,4,'Volume','Unidades de volume, cálculo de volumes e relações com capacidade.',5),(32,5,'Experimentos aleatórios e probabilidade','Espaço amostral, eventos, possibilidades e cálculo de probabilidades.',1),(33,5,'Coleta e organização de dados','Planejamento de pesquisas, coleta, classificação e organização de dados.',2),(34,5,'Tabelas e gráfic