INSERT INTO `tags` VALUES (1,'Leitura','Conhecimentos relacionados à leitura e compreensão de textos.','Linguagem',1),(2,'Interpretação de texto','Compreensão, análise e interpretação de textos.','Linguagem',1),(3,'Produção textual','Conhecimentos relacionados à escrita e produção de textos.','Linguagem',1),(4,'Análise linguística','Estudo da estrutura e do funcionamento da língua.','Linguagem',1),(5,'Oralidade','Comunicação oral, argumentação e expressão verbal.','Linguagem',1),(6,'Literatura','Estudo das manifestações e dos gêneros literários.','Linguagem',1),(7,'Língua estrangeira','Conhecimentos relacionados à aprendizagem de outros idiomas.','Linguagem',1),(8,'Raciocínio lógico','Organização do pensamento lógico e identificação de padrões.','Raciocínio',1),(9,'Resolução de problemas','Aplicação de conhecimentos para resolver situações-problema.','Raciocínio',1),(10,'Pensamento científico','Compreensão e aplicação de conhecimentos científicos.','Ciências',1),(11,'Investigação','Observação, pesquisa, experimentação e análise de informações.','Ciências',1),(12,'Educação ambiental','Relações entre sociedade, natureza e preservação ambiental.','Transversal',1),(13,'Saúde e qualidade de vida','Conhecimentos relacionados à saúde, ao corpo e ao bem-estar.','Transversal',1),(14,'Cultura e diversidade','Reconhecimento e valorização das diferentes culturas e identidades.','Transversal',1),(15,'Cidadania','Participação social, direitos, deveres e organização política.','Transversal',1),(16,'Ética','Reflexão sobre valores, princípios e condutas humanas.','Humanidades',1),(17,'Direitos humanos','Conhecimentos sobre dignidade, igualdade e direitos fundamentais.','Transversal',1),(18,'Cultura digital','Tecnologia, informação e participação no ambiente digital.','Transversal',1),(19,'Educação financeira','Uso consciente dos recursos e organização financeira.','Transversal',1),(20,'Geometria','Estudo das formas, dimensões e relações geométricas.','Matemática',1),(21,'Estatística e probabilidade','Análise de dados, estatística e fenômenos aleatórios.','Matemática',1),(22,'Ecologia','Relações entre os seres vivos e os ambientes.','Ciências',1),(23,'História e memória','Estudo dos processos históricos e da construção da memória.','Humanidades',1),(24,'Pensamento crítico','Análise, questionamento e avaliação crítica de informações.','Humanidades',1);
